begin;
select no_plan();
select is((select mock_payments_enabled from public.equipment_rental_settings),false,'rental mock payments default off');


insert into auth.users(id,email,email_confirmed_at,aud,role) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'rental-'||n||'@example.test',now(),'authenticated','authenticated' from generate_series(1,4)n;
insert into public.basic_onboarding_applications(user_id,full_name,email,phone,linkedin_url,date_of_birth,status) select id,'Rental Test',email,'9999999999','https://linkedin.com/in/test','1990-01-01','approved' from auth.users where id::text like 'd1000000%';
insert into public.staff_roles(user_id,role) values('d1000000-0000-4000-8000-000000000001','admin'),('d1000000-0000-4000-8000-000000000004','membership_reviewer');
insert into public.resources(id,location_id,slug,name,kind,capacity,max_guests,max_duration_minutes,booking_horizon_days)
select ('d2000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,l.id,'rental-fixture-'||n,'Rental fixture '||n,case when n=1 then 'workspace'::public.resource_kind else 'equipment'::public.resource_kind end,1,0,1440,10000 from generate_series(1,2)n cross join lateral(select id from public.locations limit 1)l;
insert into public.resource_booking_policies values('d2000000-0000-4000-8000-000000000001','workspace'),('d2000000-0000-4000-8000-000000000002','equipment');
insert into public.resource_hours(resource_id,day_of_week,opens_at,closes_at) select id,d,'09:00','17:00' from public.resources cross join generate_series(0,6)d where id::text like 'd2000000%';
delete from public.booking_inventory;
insert into public.booking_inventory values('d2000000-0000-4000-8000-000000000001','S01','GF','GF-10');
insert into public.inventory_locations(id,lab_location_id,code,name) select 'd3000000-0000-4000-8000-000000000001',id,'RENTAL-TEST','Rental test' from public.locations limit 1;
insert into public.asset_units(id,component_id,inventory_location_id,asset_tag) select 'd3000000-0000-4000-8000-000000000002',id,'d3000000-0000-4000-8000-000000000001','ARM-TEST-990001' from public.components limit 1;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('rental.unit',public.configure_equipment_rental_unit('d3000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000002',true,'Synthetic commissioning only')::text,true);
select set_config('rental.rate',public.approve_equipment_rental_rate(current_setting('rental.unit')::uuid,'hour',10000,now()-interval '1 day',null,0)::text,true);
select set_config('rental.dayrate',public.approve_equipment_rental_rate(current_setting('rental.unit')::uuid,'day',50000,now()-interval '1 day',null,0)::text,true);
select set_config('rental.notax',public.approve_equipment_rental_rate(current_setting('rental.unit')::uuid,'hour',10000,'2020-01-01','2021-01-01')::text,true);
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);

update public.equipment_rental_settings set mock_payments_enabled=true;
update public.booking_policy_settings set mock_grants_enabled=true;
update public.booking_products set enabled=true,price_paise=50000;
create function pg_temp.bundle(day date default '2030-01-07') returns uuid language sql as $$
 select public.create_equipment_workspace_quote(current_setting('rental.rate')::uuid,(day+time '10:00') at time zone 'Asia/Kolkata',(day+time '11:00') at time zone 'Asia/Kolkata','d2000000-0000-4000-8000-000000000001',(select id from public.booking_products where code='workspace-day'),array[day]); $$;
select throws_ok($$select pg_temp.bundle()$$,'22023','Choose a configured personal chair or whole team cabin with explicit tax','missing workspace tax rejects bundle');
update public.booking_products set tax_bps=1800 where kind in ('workspace','cabin');
update public.basic_onboarding_applications set status='revoked' where user_id='d1000000-0000-4000-8000-000000000002';
select throws_ok($$select pg_temp.bundle()$$,'42501','Approved basic membership required','revoked member cannot quote');
update public.basic_onboarding_applications set status='approved' where user_id='d1000000-0000-4000-8000-000000000002';
select set_config('bundle.id',pg_temp.bundle()::text,true);
select is((select total_paise from public.equipment_workspace_quotes where quote_id=current_setting('bundle.id')::uuid),69000::bigint,'combined quote includes equipment and explicit workspace tax');
select throws_ok($$select public.reserve_equipment_workspace_bundle(current_setting('bundle.id')::uuid)$$,'42501','Current combined mock authorization required','unpaid bundle cannot reserve');
select throws_ok($$select public.authorize_mock_equipment_bundle(current_setting('bundle.id')::uuid)$$,'42501','Website Admin required','member cannot authorize combined receipt');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select throws_ok($$select public.authorize_mock_equipment_bundle(current_setting('bundle.id')::uuid)$$,'42501','Website Admin required','membership Staff cannot authorize bundle');
set local role authenticated;
select is((select count(*)::integer from public.equipment_workspace_quotes),0,'Staff cannot read private combined quotes');
reset role;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.authorize_mock_equipment_bundle(current_setting('bundle.id')::uuid);
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
update public.booking_products set price_paise=50001 where code='workspace-day';
select throws_ok($$select public.reserve_equipment_workspace_bundle(current_setting('bundle.id')::uuid)$$,'22023','Workspace price changed; request a new quote','changed workspace price invalidates authorization');
update public.booking_products set price_paise=50000 where code='workspace-day';
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_resource_block('d2000000-0000-4000-8000-000000000001','2030-01-07 09:00+05:30','2030-01-07 17:00+05:30','maintenance','Synthetic conflict');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.reserve_equipment_workspace_bundle(current_setting('bundle.id')::uuid)$$,'23P01','Resource is no longer available for selected dates','chair conflict rejects bundle');
select is((select count(*)::integer from public.paid_access_entitlements where resource_id::text like 'd2000000%'),0,'chair conflict rolls back workspace entitlement');
delete from public.resource_reservations where resource_id='d2000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_resource_block('d2000000-0000-4000-8000-000000000002','2030-01-07 09:00+05:30','2030-01-07 17:00+05:30','maintenance','Synthetic conflict');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.reserve_equipment_workspace_bundle(current_setting('bundle.id')::uuid)$$,'22023','Resource is unavailable for maintenance','equipment conflict rejects bundle');
select is((select count(*)::integer from public.bookings where resource_id='d2000000-0000-4000-8000-000000000001'),0,'equipment conflict rolls back chair booking');
select is((select payment_state from public.equipment_rental_quotes where id=current_setting('bundle.id')::uuid),'authorized','failed bundle preserves unconsumed authorization');
delete from public.resource_reservations where resource_id='d2000000-0000-4000-8000-000000000002';
select set_config('bundle.order',public.reserve_equipment_workspace_bundle(current_setting('bundle.id')::uuid)::text,true);
select is(public.reserve_equipment_workspace_bundle(current_setting('bundle.id')::uuid),current_setting('bundle.order')::uuid,'bundle confirmation retry is idempotent');
select is((select sum(price_paise)::bigint from public.paid_access_entitlements where id=any((select entitlement_ids from public.equipment_workspace_quotes where quote_id=current_setting('bundle.id')::uuid)::uuid[])),59000::bigint,'workspace ledger equals authorized workspace plus tax');
select ok((select captured_at is not null from public.equipment_workspace_quotes where quote_id=current_setting('bundle.id')::uuid),'combined capture timestamp recorded');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select throws_ok($$select public.reserve_equipment_workspace_bundle(current_setting('bundle.id')::uuid)$$,'42501','Own combined quote required','another member cannot consume or replay bundle');
set local role authenticated;
select is((select count(*)::integer from public.equipment_workspace_quotes),0,'unrelated member cannot read combined quote');
reset role;
insert into public.organizations(id,name) values('d5000000-0000-4000-8000-000000000001','Rental team fixture');
insert into public.organization_memberships(organization_id,status,seat_allowance,starts_at,ends_at) values('d5000000-0000-4000-8000-000000000001','active',6,now()-interval '1 day','2031-01-01');
insert into public.organization_members(organization_id,user_id,role,seat_enabled) values('d5000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000002','admin',false),('d5000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000003','member',true);
insert into public.resources(id,location_id,slug,name,kind,capacity,max_guests,max_duration_minutes,booking_horizon_days) select 'd2000000-0000-4000-8000-000000000003',id,'rental-team-cabin','Rental team cabin','room',6,3,1440,10000 from public.locations limit 1;
insert into public.resource_booking_policies values('d2000000-0000-4000-8000-000000000003','cabin');
insert into public.resource_hours(resource_id,day_of_week,opens_at,closes_at) select 'd2000000-0000-4000-8000-000000000003',d,'09:00','17:00' from generate_series(0,6)d;
insert into public.booking_inventory values('d2000000-0000-4000-8000-000000000003','C01','GF','GF-01');

select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('bundle.cabin',public.create_equipment_workspace_quote(current_setting('rental.rate')::uuid,'2030-02-07 10:00+05:30','2030-02-07 11:00+05:30','d2000000-0000-4000-8000-000000000003',(select id from public.booking_products where code='cabin-month'),array[date '2030-02-01'],null,null,'d1000000-0000-4000-8000-000000000003','d5000000-0000-4000-8000-000000000001')::text,true);
select is((select seats from public.equipment_workspace_quotes where quote_id=current_setting('bundle.cabin')::uuid),6,'cabin quote sells all six seats');
select is((select workspace_paise from public.equipment_workspace_quotes where quote_id=current_setting('bundle.cabin')::uuid),300000::bigint,'cabin charges six seats for one month');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.authorize_mock_equipment_bundle(current_setting('bundle.cabin')::uuid);
select set_config('request.jwt.claims','{"sub":"d1000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select public.reserve_equipment_workspace_bundle(current_setting('bundle.cabin')::uuid)$$,'team admin without own seat books whole cabin for enabled operator');
select is((select b.member_id from public.equipment_rental_orders o join public.bookings b on b.id=o.booking_id where o.quote_id=current_setting('bundle.cabin')::uuid),'d1000000-0000-4000-8000-000000000003'::uuid,'actual member is equipment operator');
select is((select count(*)::integer from public.bookings where resource_id='d2000000-0000-4000-8000-000000000003'),28,'monthly cabin creates every open February date');
select is((select sum(price_paise)::bigint from public.paid_access_entitlements where id=any((select entitlement_ids from public.equipment_workspace_quotes where quote_id=current_setting('bundle.cabin')::uuid)::uuid[])),354000::bigint,'monthly entitlement allocation preserves exact gross total');

select * from finish();
rollback;
